1	package org.osm2world.console.commands;
2	
3	import static java.lang.Math.*;
4	import static java.util.Arrays.stream;
5	import static java.util.Objects.requireNonNullElse;
6	import static org.osm2world.console.commands.mixins.CameraOptions.*;
7	import static picocli.CommandLine.Command;
8	import static picocli.CommandLine.Option;
9	
10	import java.io.File;
11	import java.util.EnumSet;
12	import java.util.HashMap;
13	import java.util.List;
14	import java.util.Map;
15	import java.util.concurrent.Callable;
16	
17	import javax.annotation.Nullable;
18	
19	import org.osm2world.O2WConverter;
20	import org.osm2world.console.commands.mixins.*;
21	import org.osm2world.conversion.O2WConfig;
22	import org.osm2world.math.VectorXYZ;
23	import org.osm2world.math.geo.*;
24	import org.osm2world.math.shapes.AxisAlignedRectangleXZ;
25	import org.osm2world.osm.creation.JsonFileReader;
26	import org.osm2world.osm.creation.OSMDataReaderView;
27	import org.osm2world.osm.creation.OSMFileReader;
28	import org.osm2world.output.common.compression.Compression;
29	import org.osm2world.output.common.rendering.MutableCamera;
30	import org.osm2world.output.common.rendering.OrthographicUtil;
31	import org.osm2world.output.common.rendering.PerspectiveProjection;
32	import org.osm2world.output.common.rendering.Projection;
33	import org.osm2world.output.frontend_pbf.FrontendPbfOutput;
34	import org.osm2world.output.gltf.GltfFlavor;
35	import org.osm2world.output.gltf.GltfOutput;
36	import org.osm2world.output.image.ImageExporter;
37	import org.osm2world.output.image.ImageOutputFormat;
38	import org.osm2world.output.obj.ObjMultiFileOutput;
39	import org.osm2world.output.obj.ObjOutput;
40	import org.osm2world.output.povray.POVRayOutput;
41	import org.osm2world.scene.Scene;
42	import org.osm2world.scene.mesh.LevelOfDetail;
43	import org.osm2world.util.Resolution;
44	
45	import picocli.CommandLine;
46	
47	@Command(name = "convert", description = "Convert OSM data to 3D models and output the result.")
48	public class ConvertCommand implements Callable<Integer> {
49	
50		@Option(names = {"--output", "-o"}, description = "output files", arity = "1..", required = true,
51				paramLabel = "<path>")
52		List<File> outputFiles;
53	
54		@Option(names = {"--tile"}, description = "the tile to convert", paramLabel = "zoom,x,y")
55		@Nullable
56		TileNumber tile;
57	
58		@Option(names = {"--lod"}, description = "level of detail of the output", paramLabel="[01234]")
59		@Nullable
60		LevelOfDetail lod = null;
61	
62		@CommandLine.Option(names = {"--resolution"}, description = "output size in pixels",
63				paramLabel = "w,h")
64		@Nullable
65		Resolution resolution = null;
66	
67		@Option(names = {"--input_bbox"}, paramLabel="lat,lon lat,lon...",
68				description="input bounding box (does not work with all data sources)")
69		@Nullable
70		LatLonBounds inputBbox;
71	
72		@CommandLine.ArgGroup()
73		@Nullable CameraOptions cameraOptions = null;
74	
75		/* mixins */
76	
77		@CommandLine.Mixin
78		private InputOptions inputOptions;
79	
80		@CommandLine.Mixin
81		private ConfigOptions configOptions;
82	
83		@CommandLine.Mixin
84		private LoggingOptions loggingOptions;
85	
86		@CommandLine.Mixin
87		private MetadataOptions metadataOptions;
88	
89		private record SceneInputs(OSMDataReaderView osmReaderView, List<File> configFiles,
90								   Map<String, Object> extraProperties) {}
91		private final Map<SceneInputs, Scene> cachedScenes = new HashMap<>();
92	
93		@Override
94		public Integer call() throws Exception {
95	
96			var converter = new O2WConverter();
97	
98			/* validate arguments */
99	
100			String errorString = getErrorString();
101	
102			if (errorString != null) {
103				System.err.println(errorString);
104				return 1;
105			}
106	
107			/* augment and set the config */
108	
109			var extraProperties = new HashMap<>(metadataOptions.configOptionsFromMetadata(tile));
110	
111			if (lod != null) { extraProperties.put("lod", lod.ordinal()); }
112			if (loggingOptions.logDir != null) { extraProperties.put("logDir", loggingOptions.logDir.toString()); }
113	
114			O2WConfig config = configOptions.getO2WConfig(extraProperties);
115			
116			converter.setConfig(config);
117	
118			/* create the scene (or use a cached scene) */
119	
120			OSMDataReaderView osmReaderView = buildInput();
121	
122			// TODO: enable sharing (most) scene calculations across different LOD
123			var sceneKey = new SceneInputs(osmReaderView, configOptions.getConfigFiles(), extraProperties);
124	
125			Scene scene = cachedScenes.containsKey(sceneKey)
126					? cachedScenes.get(sceneKey)
127					: converter.convert(osmReaderView, null, null);
128			cachedScenes.put(sceneKey, scene);
129	
130			MapProjection proj = scene.getMapProjection();
131			assert proj != null;
132	
133			ImageExporter exporter = null;
134	
135			{ // TODO: support sharing ImageExporter across multiple outputs
136	
137				/* set camera and projection */
138	
139				MutableCamera camera;
140				Projection projection;
141	
142				ViewOptions viewOptions = getCameraViewOptions(cameraOptions);
143	
144				if (viewOptions instanceof PviewOptions pView) {
145	
146					/* perspective projection */
147	
148					LatLonEle pos = pView.pos;
149					LatLonEle lookAt = pView.lookAt;
150	
151					camera = new MutableCamera();
152					VectorXYZ posXYZ = proj.toXZ(pos.lat, pos.lon).xyz(pos.ele);
153					VectorXYZ lookAtXYZ = proj.toXZ(lookAt.lat, lookAt.lon).xyz(lookAt.ele);
154					camera.setCamera(posXYZ, lookAtXYZ);
155	
156					projection = new PerspectiveProjection(
157							pView.aspect != null ? pView.aspect :
158									resolution != null ? (double) resolution.getAspectRatio()
159											: DEFAULT_ASPECT_RATIO,
160							pView.fovy, 1, 50000);
161	
162				} else {
163	
164					/* orthographic projection */
165	
166					OviewOptions oView = (OviewOptions) viewOptions;
167	
168					double angle = oView.angle;
169					CardinalDirection from = oView.from;
170	
171					AxisAlignedRectangleXZ bounds;
172	
173					if (oView.bbox != null) {
174						bounds = OrthographicUtil.boundsXZ(proj, oView.bbox);
175					} else if (oView.tiles != null) {
176						bounds = OrthographicUtil.boundsXZ(proj, oView.tiles.latLonBounds());
177					} else if (tile != null) {
178						bounds = OrthographicUtil.boundsForTile(proj, tile);
179					} else {
180						bounds = scene.getBoundary();
181					}
182	
183					camera = OrthographicUtil.cameraForBounds(bounds, angle, from);
184					projection = OrthographicUtil.projectionForBounds(bounds, angle, from);
185	
186				}
187	
188				/* perform the actual output */
189	
190				for (File outputFile : outputFiles) {
191	
192					outputFile.getAbsoluteFile().getParentFile().mkdirs();
193	
194					String fileName = outputFile.getName().toUpperCase();
195					fileName = fileName.replaceAll("O2W\\.PBF", "O2W_PBF");
196	
197					Compression compression = Compression.NONE;
198					for (Compression c : EnumSet.of(Compression.GZ, Compression.ZIP)) {
199						if (fileName.endsWith("." + c)) {
200							compression = c;
201							fileName = fileName.replaceAll("\\." + c + "$", "");
202						}
203					}
204	
205					String extension = fileName.substring(fileName.lastIndexOf('.') + 1);
206	
207					switch (extension) {
208	
209						case "OBJ" -> {
210							Integer primitiveThresholdOBJ = config.getInteger("primitiveThresholdOBJ", null);
211							var output = (primitiveThresholdOBJ == null)
212									? new ObjOutput(outputFile, scene.getMapProjection())
213									: new ObjMultiFileOutput(outputFile, scene.getMapProjection(), primitiveThresholdOBJ);
214							output.setConfiguration(config);
215							output.outputScene(scene);
216						}
217	
218						case "GLTF", "GLB" -> {
219							AxisAlignedRectangleXZ bounds;
220							if (tile != null) {
221								bounds = OrthographicUtil.boundsForTile(scene.getMapProjection(), tile);
222							} else {
223								bounds = scene.getBoundary();
224							}
225							GltfFlavor gltfFlavor = GltfFlavor.valueOf(extension);
226							GltfOutput output = new GltfOutput(outputFile, gltfFlavor, compression);
227							output.setConfiguration(config);
228							output.outputScene(scene.getMeshesWithMetadata(config), proj.getOrigin(), bounds);
229						}
230	
231						case "POV" -> {
232							POVRayOutput output = new POVRayOutput(outputFile, camera, projection);
233							output.setConfiguration(config);
234							output.outputScene(scene);
235						}
236	
237						case "O2W_PBF" -> {
238							AxisAlignedRectangleXZ bbox;
239							if (tile != null) {
240								bbox = OrthographicUtil.boundsForTile(scene.getMapProjection(), tile);
241							} else {
242								bbox = scene.getBoundary();
243							}
244							FrontendPbfOutput output = new FrontendPbfOutput(outputFile, compression, bbox);
245							output.setConfiguration(config);
246							output.outputScene(scene);
247						}
248	
249						case "PNG", "PPM", "GD" -> {
250							if (exporter == null) {
251								ImageExporter.PerformanceParams performanceParams = determineImageExporterParams(config);
252								exporter = ImageExporter.create(config, scene.getBoundary(),
253										output -> output.outputScene(scene),
254										performanceParams.resolution(), performanceParams.unbufferedRendering());
255							}
256							Resolution resolution = determineResolution();
257							ImageOutputFormat imageFormat = ImageOutputFormat.valueOf(extension) ;
258							exporter.writeImageFile(outputFile, imageFormat,
259									resolution.width, resolution.height,
260									camera, projection);
261						}
262	
263						default -> System.err.println(
264								"Cannot determine output type for output file, skipping it: " + outputFile);
265	
266					}
267	
268				}
269	
270			}
271	
272			if (exporter != null) {
273				exporter.freeResources();
274			}
275	
276			return 0;
277	
278		}
279	
280		/** validates the arguments and returns an error string iff they are incorrect */
281		private @Nullable String getErrorString() {
282	
283			switch (inputOptions.inputMode) {
284	
285				case FILE -> {
286					if (inputOptions.input == null) {
287						return "input file parameter is required (or choose a different input mode)";
288					} else {
289						OSMDataReaderView input = buildInput();
290						if (!(input.reader instanceof OSMFileReader || input.reader instanceof JsonFileReader)
291								&& inputBbox == null && tile == null) {
292							return "a tile number or input bounding box is required for database input files";
293						}
294					}
295				}
296	
297				case OVERPASS -> {
298					if (inputOptions.inputQuery == null && inputBbox == null && tile == null) {
299						return "either a bounding box, a tile, or a query string is required for Overpass";
300					}
301				}
302	
303			}
304	
305			if (getCameraViewOptions(cameraOptions) instanceof OviewOptions oView
306					&& oView.tiles != null && oView.bbox != null) {
307				return "define *either* tiles or bounding box for orthographic view";
308			}
309	
310			return null;
311	
312		}
313	
314	
315		private OSMDataReaderView buildInput() {
316	
317			GeoBounds bounds = null;
318	
319			if (inputBbox != null) {
320				bounds = inputBbox;
321			} else if (tile != null) {
322				bounds = tile;
323			}
324	
325			return inputOptions.buildInput(bounds);
326	
327		}
328	
329		private ViewOptions getCameraViewOptions(@Nullable CameraOptions cameraOptions) {
330			if (cameraOptions != null) {
331				return cameraOptions.oviewOptions != null ? cameraOptions.oviewOptions : cameraOptions.pviewOptions;
332			} else {
333				return new OviewOptions();
334			}
335		}
336	
337		private Resolution determineResolution() {
338	
339			ViewOptions viewOptions = getCameraViewOptions(cameraOptions);
340	
341			double oviewAngle = viewOptions instanceof OviewOptions oView
342					? oView.angle
343					: new OviewOptions().angle;
344	
345			double aspectRatio = viewOptions instanceof PviewOptions pView
346					? requireNonNullElse(pView.aspect, DEFAULT_ASPECT_RATIO)
347					: 1.0 / sin(toRadians(oviewAngle));
348	
349			return requireNonNullElse(resolution,
350					new Resolution(800, (int) round(800 / aspectRatio)));
351	
352		}
353	
354		/**
355		 * Optimizes an {@link ImageExporter}'s performance settings for use with a particular config
356		 * and a particular group of outputs.
357		 */
358		private ImageExporter.PerformanceParams determineImageExporterParams(O2WConfig config) {
359	
360			int canvasLimit = config.canvasLimit();
361	
362			/* find out what number and size of image file requests to expect */
363	
364			int expectedFileCalls = 0;
365			int expectedMaxSizeX = 1;
366			int expectedMaxSizeY = 1;
367			boolean perspectiveProjection = false;
368	
369			for (File outputFile : outputFiles) {
370	
371				if (stream(ImageOutputFormat.values()).anyMatch(it ->
372						outputFile.getName().toUpperCase().contains("." + it))) {
373					expectedFileCalls += 1;
374					expectedMaxSizeX = max(expectedMaxSizeX, determineResolution().width);
375					expectedMaxSizeY = max(expectedMaxSizeY, determineResolution().height);
376					perspectiveProjection |= getCameraViewOptions(cameraOptions) instanceof PviewOptions;
377				}
378	
379			}
380	
381			boolean onlyOneRenderPass = (expectedFileCalls <= 1
382					&& expectedMaxSizeX <= canvasLimit
383					&& expectedMaxSizeY <= canvasLimit);
384	
385			/* call the constructor */
386	
387			boolean unbufferedRendering = onlyOneRenderPass
388					|| config.forceUnbufferedPNGRendering();
389	
390			int pBufferSizeX, pBufferSizeY;
391	
392			if (perspectiveProjection) {
393				pBufferSizeX = expectedMaxSizeX;
394				pBufferSizeY = expectedMaxSizeY;
395			} else {
396				pBufferSizeX = min(canvasLimit, expectedMaxSizeX);
397				pBufferSizeY = min(canvasLimit, expectedMaxSizeY);
398			}
399	
400			return new ImageExporter.PerformanceParams(pBufferSizeX, pBufferSizeY, unbufferedRendering);
401	
402		}
403	
404	}
