1655	
1656	// ===== Mishkenot Zvulun: real neighbourhood at REAL-WORLD SCALE =====
1657	// Buildings come from assets/mishkenot/buildings.glb (exported in metres, ~422x566m,
1658	// up to ~50m tall); trees are grafted from the 3MF world.bin. 1 game unit = 1 metre,
1659	// so the ~3.8m kart is dwarfed by the houses exactly as in real life.
1660	const MISH_SCALE = 1.0;
1661	let mishGroup = null;
1662	async function buildMishkenotWorld(){
1663	  const BLD_TINTS=[0xf1ede4,0xe7dcc6,0xd7d8d2,0xdcc9a0,0xcdd4d8,0xeae2cf];
1664	  // hide the Castle-era road ribbon + green ground plane built once at load
