1666	  hemi.intensity=0.7; sun.intensity=1.05;
1667	  // open ground for the neighbourhood to sit on
1668	  const ground=new THREE.Mesh(new THREE.PlaneGeometry(2600,2600),
1669	    new THREE.MeshLambertMaterial({color:0x93a06f}));
1670	  ground.rotation.x=-Math.PI/2; ground.position.y=-0.05; ground.receiveShadow=true; scene.add(ground);
1671	  try{
1672	    const outer=new THREE.Group(), inner=new THREE.Group(); outer.add(inner);
1673	    // 1) BUILDINGS — the real GLB (metres); tint each building for variety
1674	    const gltf=await new Promise((res,rej)=>new THREE.GLTFLoader().load('/assets/mishkenot/buildings.glb',res,undefined,rej));
1675	    let bi=0;
1676	    gltf.scene.traverse(o=>{
1677	      if(o.isMesh){ o.material=new THREE.MeshLambertMaterial({color:BLD_TINTS[bi++ % BLD_TINTS.length]});
1678	        o.castShadow=true; o.receiveShadow=true; }
1679	      else if(o.isLine||o.isLineSegments){ o.visible=false; }   // stray fat-line edges
1680	    });
1681	    const gb=new THREE.Box3().setFromObject(gltf.scene);
1682	    const cG=gb.getCenter(new THREE.Vector3()), sG=gb.getSize(new THREE.Vector3());
