}

/* ============================ SHARED VISUAL POLISH ============================ */
/* Applied on top of every world (themed per world): a gradient sky dome with
   drifting clouds, a lush flowery/grassy roadside, and wooden plank guard-rails —
   the bright cartoon-racer look from the reference art. */
const VTHEME={
  castle:{ sky:[0x3f8fd4,0xc6e8ff], cloud:0xffffff,
    flowers:[0xe6394a,0xffd23f,0xffffff,0xc46cf0,0xff7a3d,0x5b9bff],
    blade:0x57a544, bush:0x2f8a3e, fillProb:.85, spread:5.5, sides:[1,-1], rails:true, rock:false },
  beach:{ sky:[0xef9a5c,0xffe6cf], cloud:0xffe0c4,
    flowers:[0xff7aa8,0xffffff,0xffd24a,0xff9ec2],
    blade:0x6cae5f, bush:0x4f9e57, fillProb:.6, spread:9, sides:[1], rails:false, rock:false },
  desert:{ sky:[0xe3aa50,0xf7e6b8], cloud:0xf3ddbb,
    flowers:[0xff8a3d,0xffffff,0xe6c84a],
    blade:0xb39a52, bush:0x4f8a3a, fillProb:.5, spread:7, sides:[1,-1], rails:false, rock:true },
  // city boulevard: grassy verges + street trees, light hazy Paris sky
  sarcelles:{ sky:[0x8fb6dd,0xd7e6f2], cloud:0xffffff,
    flowers:[0xffd23f,0xffffff,0xe6394a],
    blade:0x6f9e4e, bush:0x3f7e3a, fillProb:.5, spread:6, sides:[1,-1], rails:false, rock:false },
  // real Netanya neighbourhood: the mesh carries its own greenery, so scatter nothing
  mishkenot:{ sky:[0x4f97d8,0xbfe0f5], cloud:0xffffff,
    flowers:[0xffd23f,0xffffff,0xe6394a],
    blade:0x6f9e4e, bush:0x3f7e3a, fillProb:0, spread:6, sides:[], rails:false, rock:false },
};
function inSkip(i,skips){
  for(const [c,r] of skips){ let d=Math.abs(i-c); d=Math.min(d,N-d); if(d<=r) return true; }
  return false;
}
function skipFor(w){
  const z=[[0,7],[Math.round(.985*N),7]];
  if(w==='castle') z.push([Math.round(CASTLE_T*N),11],[Math.round(TUNNEL_T*N),13],[Math.round(.8*N),6]);
  else if(w==='beach') z.push([146,18]);   // bridge inlet (BR0..BR1)
  else if(w==='desert') z.push([Math.round(SPHINX_T*N),10],[Math.round(TOMB_T*N),13],[Math.round(OASIS_T*N),13]);
  return z;
}
function makeSky(theme){
  if(skyDome){ scene.remove(skyDome); skyDome.material.map.dispose(); skyDome.material.dispose(); skyDome.geometry.dispose(); }
  const hex=v=>'#'+(v>>>0).toString(16).padStart(6,'0');
  const cv=document.createElement('canvas'); cv.width=8; cv.height=256;
  const cx=cv.getContext('2d');
  const grd=cx.createLinearGradient(0,0,0,256);
  grd.addColorStop(0,   hex(theme.sky[0]));
  grd.addColorStop(.62, hex(theme.sky[1]));
  grd.addColorStop(1,   hex(theme.sky[1]));
  cx.fillStyle=grd; cx.fillRect(0,0,8,256);
  const tex=new THREE.CanvasTexture(cv);
  skyDome=new THREE.Mesh(new THREE.SphereGeometry(600,24,16),
    new THREE.MeshBasicMaterial({map:tex,side:THREE.BackSide,fog:false,depthWrite:false}));
  skyDome.renderOrder=-1; scene.add(skyDome);
  scene.background.setHex(theme.sky[1]);
}
function makeClouds(col){
  if(cloudLayer){ scene.remove(cloudLayer); }
  cloudLayer=new THREE.Group(); scene.add(cloudLayer);
  const m=new THREE.MeshBasicMaterial({color:col,fog:false,transparent:true,opacity:.96});
  const geo=new THREE.SphereGeometry(1,8,6);
  for(let c=0;c<16;c++){
    const ang=Math.random()*Math.PI*2;
    const rad=150+Math.random()*200;
    const cy=72+Math.random()*78;
    const cl=new THREE.Group();
    cl.position.set(Math.cos(ang)*rad, cy, Math.sin(ang)*rad);
    cl.rotation.y=Math.random()*6;
    const puffs=3+(c%3);
    for(let p=0;p<puffs;p++){
      const s=9+Math.random()*13;
      const puff=new THREE.Mesh(geo,m);
      puff.scale.set(s, s*(.5+Math.random()*.18), s*.8);
      puff.position.set((p-puffs/2)*s*.85, (Math.random()-.5)*s*.4, (Math.random()-.5)*s*.6);
      cl.add(puff);
    }
    cloudLayer.add(cl);
  }
}
function scatterVegetation(theme,skips){
  const flowerMats=theme.flowers.map(c=>new THREE.MeshLambertMaterial({color:c}));
  const stemMat=new THREE.MeshLambertMaterial({color:0x3f7a2e});
  const bladeMat=new THREE.MeshLambertMaterial({color:theme.blade});
  const bushMat=new THREE.MeshLambertMaterial({color:theme.bush});
  const rockMat=new THREE.MeshLambertMaterial({color:0xa89880});
  const stemGeo=new THREE.BoxGeometry(.07,.45,.07);
  const petalGeo=new THREE.BoxGeometry(.36,.36,.12);
  const bladeGeo=new THREE.BoxGeometry(.05,.75,.05);
  const bushGeo=new THREE.IcosahedronGeometry(.6,0);
  const rockGeo=new THREE.DodecahedronGeometry(.7,0);
  for(let i=0;i<N;i+=3){
    if(inSkip(i,skips)) continue;
    const p=samples[i], n=normals[i], tan=tangents[i];
    for(const s of theme.sides){
      if(Math.random()>theme.fillProb) continue;
      const off=HALF_W+2.2+Math.random()*theme.spread;
      const along=(Math.random()-.5)*2.4;
      const x=p.x+n.x*off*s+tan.x*along, z=p.z+n.z*off*s+tan.z*along;
      const r=Math.random();
      if(theme.rock && r<.18){
        const rk=new THREE.Mesh(rockGeo,rockMat);
        const sc=.6+Math.random()*1.1; rk.scale.set(sc,sc*.7,sc);
        rk.position.set(x,sc*.3,z); rk.rotation.set(Math.random(),Math.random(),Math.random());
        rk.castShadow=true; rk.receiveShadow=true; scene.add(rk);
      } else if(r<.5){ // flower clump
        const g=new THREE.Group(); g.position.set(x,0,z); scene.add(g);
        const fc=flowerMats[(Math.random()*flowerMats.length)|0];
        const blooms=1+(Math.random()<.6?1:0);
        for(let b=0;b<blooms;b++){
          const bx=(Math.random()-.5)*.5, bz=(Math.random()-.5)*.5;
          const st=new THREE.Mesh(stemGeo,stemMat); st.position.set(bx,.22,bz); g.add(st);
          const pt=new THREE.Mesh(petalGeo,fc); pt.position.set(bx,.5,bz); pt.rotation.y=Math.random()*3;
          pt.castShadow=true; g.add(pt);
          const pt2=new THREE.Mesh(petalGeo,fc); pt2.position.set(bx,.5,bz); pt2.rotation.y=pt.rotation.y+Math.PI/2; g.add(pt2);
        }
      } else if(r<.8){ // grass tuft
        const g=new THREE.Group(); g.position.set(x,0,z); g.rotation.y=Math.random()*6; scene.add(g);
        for(let b=0;b<3;b++){
          const bl=new THREE.Mesh(bladeGeo,bladeMat);
          bl.position.set((b-1)*.16,.36,0); bl.rotation.z=(b-1)*.28; g.add(bl);
        }
      } else { // little bush
        const g=new THREE.Group(); g.position.set(x,0,z); scene.add(g);
        const sc=.8+Math.random()*.8;
        for(const [ox,oy,oz,cs] of [[0,.55*sc,0,1],[.5*sc,.7*sc,.2*sc,.7],[-.4*sc,.6*sc,-.3*sc,.65]]){
          const lf=new THREE.Mesh(bushGeo,bushMat); lf.scale.setScalar(cs*sc);
          lf.position.set(ox,oy,oz); lf.castShadow=true; g.add(lf);
        }
      }
    }
  }
}
function addPlankRails(skips){
  const postM=new THREE.MeshLambertMaterial({color:0x7a5630});
  const plankM=new THREE.MeshLambertMaterial({color:0xa06b38});
  const off=HALF_W+1.4, postGeo=new THREE.BoxGeometry(.32,1.7,.32);
  for(const s of [1,-1]){
    for(let i=0;i<N;i+=5){
      if(inSkip(i,skips)) continue;
      const p=samples[i],n=normals[i];
      const post=new THREE.Mesh(postGeo,postM);
      post.position.set(p.x+n.x*off*s,.85,p.z+n.z*off*s);
      post.castShadow=true; scene.add(post);
      const i2=(i+5)%N;
      if(inSkip(i2,skips)) continue;
      const q=samples[i2],n2=normals[i2];
      const ax=p.x+n.x*off*s, az=p.z+n.z*off*s;
      const bx=q.x+n2.x*off*s, bz=q.z+n2.z*off*s;
      const len=Math.hypot(bx-ax,bz-az)+.25, rot=Math.atan2(bx-ax,bz-az);
      for(const hy of [.6,1.2]){
        const pl=new THREE.Mesh(new THREE.BoxGeometry(.13,.34,len),plankM);
        pl.position.set((ax+bx)/2,hy,(az+bz)/2); pl.rotation.y=rot; pl.castShadow=true; scene.add(pl);
      }
    }
  }
}
function enhanceWorldVisuals(w){
  const theme=VTHEME[w]||VTHEME.castle;
  const skips=skipFor(w);
  makeSky(theme);
  makeClouds(theme.cloud);
  scatterVegetation(theme,skips);
  if(theme.rails) addPlankRails(skips);
}

// ===== Mishkenot Zvulun: real neighbourhood at REAL-WORLD SCALE =====
// Buildings come from assets/mishkenot/buildings.glb (exported in metres, ~422x566m,
// up to ~50m tall); trees are grafted from the 3MF world.bin. 1 game unit = 1 metre,
// so the ~3.8m kart is dwarfed by the houses exactly as in real life.
const MISH_SCALE = 1.0;
let mishGroup = null;
async function buildMishkenotWorld(){
  const BLD_TINTS=[0xf1ede4,0xe7dcc6,0xd7d8d2,0xdcc9a0,0xcdd4d8,0xeae2cf];
  // hide the Castle-era road ribbon + green ground plane built once at load
  trackMeshes.forEach(m=>{ m.visible=false; });
  hemi.intensity=0.7; sun.intensity=1.05;
  // open ground for the neighbourhood to sit on
  const ground=new THREE.Mesh(new THREE.PlaneGeometry(2600,2600),
    new THREE.MeshLambertMaterial({color:0x93a06f}));
  ground.rotation.x=-Math.PI/2; ground.position.y=-0.05; ground.receiveShadow=true; scene.add(ground);
  try{
    const outer=new THREE.Group(), inner=new THREE.Group(); outer.add(inner);
    // 1) BUILDINGS — the real GLB (metres); tint each building for variety
    const gltf=await new Promise((res,rej)=>new THREE.GLTFLoader().load('/assets/mishkenot/buildings.glb',res,undefined,rej));
    let bi=0;
    gltf.scene.traverse(o=>{
      if(o.isMesh){ o.material=new THREE.MeshLambertMaterial({color:BLD_TINTS[bi++ % BLD_TINTS.length]});
        o.castShadow=true; o.receiveShadow=true; }
      else if(o.isLine||o.isLineSegments){ o.visible=false; }   // stray fat-line edges
    });
    const gb=new THREE.Box3().setFromObject(gltf.scene);
    const cG=gb.getCenter(new THREE.Vector3()), sG=gb.getSize(new THREE.Vector3());
    inner.add(gltf.scene);
    // 2) TREES — from the 3MF, fitted horizontally into the GLB extent, on the ground
    const M=await (await fetch('/assets/mishkenot/world.json')).json();
    const buf=await (await fetch('/assets/mishkenot/world.bin')).arrayBuffer();
    const tp=M.parts.find(p=>p.role==='tree');
    if(tp){
      // GLB loads Y-up; 3MF is Z-up. Map 3MF(x,y,z) -> GLB(x, height y, z).
      const c3x=(M.bbox.min[0]+M.bbox.max[0])/2, c3y=(M.bbox.min[1]+M.bbox.max[1])/2;
      const sxh=sG.x/(M.bbox.max[0]-M.bbox.min[0]);   // 3MF x -> GLB x (horizontal)
      const szh=sG.z/(M.bbox.max[1]-M.bbox.min[1]);   // 3MF y -> GLB z (horizontal)
      const src=new Float32Array(buf, M.bin.positions.byteOffset+tp.vStart*12, tp.vCount*3);
      const P=new Float32Array(src.length);
      for(let i=0;i<src.length;i+=3){
        P[i]  =(src[i]  -c3x)*sxh + cG.x;                    // x
        P[i+1]=(src[i+2]-tp.bbox.min[2])*sxh + gb.min.y;     // 3MF z(height) -> GLB y, on ground
        P[i+2]=(src[i+1]-c3y)*szh + cG.z;                    // 3MF y -> GLB z
      }
      const idx=new Uint32Array(buf, M.bin.indices.byteOffset+tp.iStart*4, tp.iCount);
      const tg=new THREE.BufferGeometry();
      tg.setAttribute('position', new THREE.BufferAttribute(P,3));
      tg.setIndex(new THREE.BufferAttribute(idx.slice(),1));
      tg.computeVertexNormals();
      inner.add(new THREE.Mesh(tg, new THREE.MeshLambertMaterial({color:0x478f43, side:THREE.DoubleSide})));
    }
    // 3) centre on XZ, sit on y=0 (GLB already loads Y-up — no rotation), scale to metres
    inner.position.set(-cG.x, -gb.min.y, -cG.z);
    outer.scale.setScalar(MISH_SCALE);
    scene.add(outer); mishGroup=outer;
    if(window.__dbg) window.__dbg.mishGroup=outer;
    console.log('[mishkenot] GLB buildings + 3MF trees; footprint',
      Math.round(sG.x)+'x'+Math.round(sG.z)+'m, tallest', Math.round(sG.y)+'m');
  }catch(e){ console.error('[mishkenot] load failed:', e); }
}

function buildWorld(w){
  if(buildWorld._done) return; buildWorld._done=true;
  if(w==='sarcelles'){
    setTrackData(SARCELLES_CTRL);
    buildTrackMeshes({road:0x4a4d54, ground:0x8f9483});
    buildSarcellesWorld(); enhanceWorldVisuals('sarcelles');
    setPickupsEnabled(false);
  }
  else if(w==='mishkenot'){
    setTrackData(MISHKENOT_CTRL);
    buildMishkenotWorld();
    enhanceWorldVisuals('mishkenot');
    setPickupsEnabled(false);
  }
  else if(w==='beach'){ setPickupsEnabled(true); buildBeachWorld(); enhanceWorldVisuals('beach'); }
  else if(w==='desert'){ setPickupsEnabled(true); buildDesertWorld(); enhanceWorldVisuals('desert'); }
  else { setPickupsEnabled(true); buildCastleWorld(); buildCastleTrees(); enhanceWorldVisuals('castle'); }
}

