let countT=0, countEnd=0, pendingWb=false;
const TOTAL_LAPS=3;
let finishCounter=0;
// countdown follows the WALL CLOCK (frame hitches while the world uploads to the
// GPU must not stretch it, or online clients drift apart)
function beginCountdown(){
  state='countdown'; countT=3.5; countEnd=performance.now()/1000+3.5;
  beep(440,.15);
}

let offlineObstacleMode=false;
function startRace(world){
  buildWorld(world);                 // build/swap the track FIRST so karts spawn on it
  if(karts.length===0) setupOffline();
  document.getElementById('startOverlay').style.display='none';
  offlineObstacleMode=document.getElementById('obsChk').checked;
  // obstacle course: the building starts BEFORE the first race, round 1
  if(offlineObstacleMode) startPlacing(1);
  else beginCountdown();
}
document.getElementById('startCastle').addEventListener('click',()=>startRace('castle'));
document.getElementById('startBeach').addEventListener('click',()=>startRace('beach'));
document.getElementById('startDesert').addEventListener('click',()=>startRace('desert'));
document.getElementById('startSarcelles').addEventListener('click',()=>startRace('sarcelles'));
document.getElementById('startMishkenot').addEventListener('click',()=>startRace('mishkenot'));
// deep-link / headless: ?world=<name> jumps straight into that world
{ const wq=new URLSearchParams(location.search).get('world');
  if(wq && ['castle','beach','desert','sarcelles','mishkenot'].includes(wq)) startRace(wq); }
// offline racer picker: choose which animal YOU race as (rivals take the rest)
document.querySelectorAll('#animalPick .animBtn').forEach(b=>{
  b.addEventListener('click',()=>{
    offlineAnimal=b.dataset.animal;
    document.querySelectorAll('#animalPick .animBtn').forEach(x=>x.classList.toggle('sel',x===b));
  });
});
// Render each racer's REAL in-game kart (the exact makeKart/makeDriver meshes you drive)
// to a transparent PNG, so the intro line-up matches the karts in the race precisely.
(function(){
  try{
    const order=['chicken','dog','sheep','cat','frog'];
    const RS=420;
    const rr=new THREE.WebGLRenderer({antialias:true, alpha:true, preserveDrawingBuffer:true});
    rr.setPixelRatio(2); rr.setSize(RS,RS); rr.setClearColor(0x000000,0);
    const sc=new THREE.Scene();
    sc.add(new THREE.HemisphereLight(0xffffff,0x55603a,1.1));

