function buildTrackMeshes(opts){
  opts=opts||{};
  clearTrackMeshes();
  // road surface
  {
    const pos=[],idx=[],uv=[];
    for(let i=0;i<=N;i++){
      const j=i%N, c=samples[j], n=normals[j];
      pos.push(c.x+n.x*HALF_W,.06,c.z+n.z*HALF_W, c.x-n.x*HALF_W,.06,c.z-n.z*HALF_W);
      uv.push(0,i*.3, 1,i*.3);
    }
    for(let i=0;i<N;i++){const a=i*2;idx.push(a,a+1,a+2, a+1,a+3,a+2);}
    const g=new THREE.BufferGeometry();
    g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
    g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
    g.setIndex(idx); g.computeVertexNormals();
    roadMesh=new THREE.Mesh(g,new THREE.MeshLambertMaterial({color:opts.road||0x5f636b,side:THREE.DoubleSide}));
    roadMesh.receiveShadow=true; scene.add(roadMesh); trackMeshes.push(roadMesh);
  }
  // center dashes + edge lines
  {
    const dashG=new THREE.BoxGeometry(.5,.03,2.6);
    const dashM=new THREE.MeshBasicMaterial({color:0xffffff});
    for(let i=0;i<N;i+=6){
      const m=new THREE.Mesh(dashG,dashM);
      m.position.copy(samples[i]); m.position.y=.1;
      m.rotation.y=Math.atan2(tangents[i].x,tangents[i].z);
      scene.add(m); trackMeshes.push(m);
    }
    const edgeM=new THREE.MeshBasicMaterial({color:0xf4f4f4});
    const edgeG=new THREE.BoxGeometry(.45,.03,3.2);
    for(let i=0;i<N;i+=2){
      for(const s of [1,-1]){
        const m=new THREE.Mesh(edgeG,edgeM);
        m.position.set(samples[i].x+normals[i].x*HALF_W*s*.97,.1,samples[i].z+normals[i].z*HALF_W*s*.97);
        m.rotation.y=Math.atan2(tangents[i].x,tangents[i].z);
        scene.add(m); trackMeshes.push(m);
      }
    }
  }
  // start/finish checkered strip
  {
    const g=new THREE.PlaneGeometry(ROAD_W,3,8,2);
    const cvs=document.createElement('canvas');cvs.width=64;cvs.height=16;
    const cx=cvs.getContext('2d');
    for(let x=0;x<8;x++)for(let y=0;y<2;y++){cx.fillStyle=(x+y)%2?'#111':'#eee';cx.fillRect(x*8,y*8,8,8);}
    const tex=new THREE.CanvasTexture(cvs);
    const m=new THREE.Mesh(g,new THREE.MeshBasicMaterial({map:tex}));
    m.rotation.x=-Math.PI/2;
    m.position.copy(samples[0]);m.position.y=.12;
    m.rotation.z=-Math.atan2(tangents[0].x,tangents[0].z);
    scene.add(m); trackMeshes.push(m);
  }
  // ground (castle default; beach swaps for park/sand/sea, sarcelles for pavement)
  groundMesh=new THREE.Mesh(new THREE.PlaneGeometry(900,900),
    new THREE.MeshLambertMaterial({color:opts.ground||0x4f9e3e}));
  groundMesh.rotation.x=-Math.PI/2; groundMesh.receiveShadow=true;
  scene.add(groundMesh); trackMeshes.push(groundMesh);
}
buildTrackMeshes();

