// real metres, Y-up, already centred on origin with the ground at y=0 and the
// Eiffel Tower ~330 m tall. 1 game unit = 1 metre, so the ~3.8 m kart is dwarfed.
let parisGroup = null;
async function buildParisWorld(){
  if(groundMesh) groundMesh.visible=false;     // the GLB carries its own ground/roads/greens
  hemi.intensity=0.78; sun.intensity=1.05;
  // wide base plane below the city to hide any clip-edge gaps at the play-area border
  const base=new THREE.Mesh(new THREE.PlaneGeometry(1800,1800),
    new THREE.MeshLambertMaterial({color:0x7d9b63}));
  base.rotation.x=-Math.PI/2; base.position.y=-0.6; base.receiveShadow=true; scene.add(base);
  try{
    const gltf=await new Promise((res,rej)=>new THREE.GLTFLoader().load('/assets/paris/world.glb',res,undefined,rej));
    const root=gltf.scene;
    root.traverse(o=>{ if(o.isMesh){
      // keep the baked per-vertex colours, but use the game's Lambert lighting model
      o.material=new THREE.MeshLambertMaterial({vertexColors:true, side:THREE.DoubleSide});
      o.castShadow=true; o.receiveShadow=true;
    } else if(o.isLine||o.isLineSegments){ o.visible=false; } });
    scene.add(root); parisGroup=root;
    if(window.__dbg) window.__dbg.parisGroup=root;
    const bb=new THREE.Box3().setFromObject(root), sz=bb.getSize(new THREE.Vector3());
    console.log('[paris] OSM2World world.glb loaded; footprint',
      Math.round(sz.x)+'x'+Math.round(sz.z)+'m, tallest', Math.round(sz.y)+'m');
  }catch(e){ console.error('[paris] load failed:', e); }
}

