      inner.add(new THREE.Mesh(tg, new THREE.MeshLambertMaterial({color:0x478f43, side:THREE.DoubleSide})));
    }
    // 3) centre on XZ, sit on y=0 (GLB already loads Y-up — no rotation), scale to metres
    inner.position.set(-cG.x, -gb.min.y, -cG.z);
    outer.scale.setScalar(MISH_SCALE);
    scene.add(outer); mishGroup=outer;
    if(window.__dbg) window.__dbg.mishGroup=outer;
    console.log('[mishkenot] GLB buildings + 3MF trees; footprint',
      Math.round(sG.x)+'x'+Math.round(sG.z)+'m, tallest', Math.round(sG.y)+'m');
  }catch(e){ console.error('[mishkenot] load failed:', e); }
}

