function legendFor(b){var o=ovr[b.id];return o?TYPES[o.type].legend:'#888';}
function drawOverlay(){dctx.clearRect(0,0,W,H);
  for(var i=0;i<BLD.length;i++){var b=BLD[i],f=b.foot;if(!f.length)continue;
    dctx.beginPath();for(var k=0;k<f.length;k++){var s=toScreen(f[k][0],f[k][1]);k?dctx.lineTo(s.x,s.y):dctx.moveTo(s.x,s.y);}dctx.closePath();
    dctx.fillStyle=legendFor(b)+(b===sel?'':'aa');dctx.globalAlpha=b===sel?0.85:0.55;dctx.fill();dctx.globalAlpha=1;
    dctx.lineWidth=b===sel?3:1;dctx.strokeStyle=b===sel?'#111':'#33333355';dctx.stroke();}
