  if(dragged){var a=worldAt(lastPx.x,lastPx.y),b=worldAt(e.clientX,e.clientY);if(a&&b){center.x+=a.x-b.x;center.z+=a.z-b.z;buildCam();render();}lastPx={x:e.clientX,y:e.clientY};}});
