  if(b4&&af){center.x+=b4.x-af.x;center.z+=b4.z-af.z;buildCam();}render();},{passive:false});

document.querySelectorAll('.ty').forEach(function(btn){btn.onclick=function(){setType(btn.dataset.t);};});
