    scene.add(g.scene);var bb=new THREE.Box3().setFromObject(g.scene),c=bb.getCenter(new THREE.Vector3()),s=bb.getSize(new THREE.Vector3());
    center={x:c.x,z:c.z};halfH=Math.max(s.x,s.z)*0.58;resize();
  });
