      var x=-W/2+(c+0.5)*(W/colW);
      if(f===0 && Math.abs(x)<1.3) continue;      // leave room for the door
      g.add(box(winW,winH,0.14,glass,x,y,D/2+0.02));
      g.add(box(winW,winH,0.14,glass,x,y,-D/2-0.02));
