66	var sun=new THREE.DirectionalLight(0xfff1d0,0.9); sun.position.set(0.4,1,0.25); scene.add(sun);
67	var plane=new THREE.Plane(new THREE.Vector3(0,1,0),0), ray=new THREE.Raycaster();
68	var cam,center={x:0,z:0},halfH=600,W=1,H=1,DPR=Math.min(2,window.devicePixelRatio||1);
69	var BLD=[],ovr={},sel=null,svOff=0;
70	
71	function resize(){W=innerWidth;H=innerHeight;renderer.setPixelRatio(DPR);renderer.setSize(W,H,false);
72	  drc.width=W*DPR;drc.height=H*DPR;drc.style.width=W+'px';drc.style.height=H+'px';dctx.setTransform(DPR,0,0,DPR,0,0);buildCam();render();}
73	function buildCam(){var asp=W/H,hw=halfH*asp;cam=new THREE.OrthographicCamera(-hw,hw,halfH,-halfH,0.1,20000);
74	  cam.position.set(center.x,5000,center.z);cam.up.set(0,0,-1);cam.lookAt(center.x,0,center.z);cam.updateProjectionMatrix();cam.updateMatrixWorld();}
75	function worldAt(px,py){var ndc=new THREE.Vector2((px/W)*2-1,-((py/H)*2-1));ray.setFromCamera(ndc,cam);
76	  var h=new THREE.Vector3();return ray.ray.intersectPlane(plane,h)?{x:h.x,z:h.z}:null;}
77	function toScreen(x,z){var v=new THREE.Vector3(x,0,z).project(cam);return {x:(v.x*0.5+0.5)*W,y:(-v.y*0.5+0.5)*H};}
78	function render(){renderer.render(scene,cam);drawOverlay();}
79	function legendFor(b){var o=ovr[b.id];return o?TYPES[o.type].legend:'#888';}
80	function drawOverlay(){dctx.clearRect(0,0,W,H);
81	  for(var i=0;i<BLD.length;i++){var b=BLD[i],f=b.foot;if(!f.length)continue;var o=ovr[b.id];
82	    dctx.beginPath();for(var k=0;k<f.length;k++){var s=toScreen(f[k][0],f[k][1]);k?dctx.lineTo(s.x,s.y):dctx.moveTo(s.x,s.y);}dctx.closePath();
83	    if(o){dctx.fillStyle=TYPES[o.type].legend;dctx.globalAlpha=b===sel?0.9:0.6;dctx.fill();dctx.globalAlpha=1;}
84	    else if(b===sel){dctx.fillStyle='#888';dctx.globalAlpha=0.55;dctx.fill();dctx.globalAlpha=1;}
85	    dctx.lineWidth=b===sel?3:1.2;dctx.strokeStyle=b===sel?'#111':(o?'#222':'#ffffffaa');dctx.stroke();}
86	}
87	function ptIn(b,x,z){var f=b.foot,c=false;for(var i=0,j=f.length-1;i<f.length;j=i++){
88	  var xi=f[i][0],zi=f[i][1],xj=f[j][0],zj=f[j][1];if(((zi>z)!=(zj>z))&&(x<(xj-xi)*(z-zi)/(zj-zi)+xi))c=!c;}return c;}
89	
90	function selectAt(px,py){var w=worldAt(px,py);if(!w)return;var found=null;
91	  for(var i=0;i<BLD.length;i++){if(ptIn(BLD[i],w.x,w.z)){found=BLD[i];break;}}
92	  sel=found;svOff=0;showSel();render();}
93	function showSel(){
94	  var sd=document.getElementById('sel'),ty=document.getElementById('types'),sv=document.getElementById('sv'),svr=document.getElementById('svrow');
95	  if(!sel){sd.textContent='No building selected.';ty.style.display='none';sv.style.display='none';svr.style.display='none';return;}
96	  var o=ovr[sel.id];
97	  sd.innerHTML='<b>Building '+sel.id+'</b><br>footprint ~'+sel.area+' m² '+(sel.levels?('· OSM levels '+sel.levels):'')+
98	    '<br>now: '+(o?('<b>Type '+o.type+'</b>, '+o.lv+' storeys'):'<i>unset</i>');
99	  ty.style.display='block';sv.style.display='block';svr.style.display='flex';
100	  loadSV();
101	  document.querySelectorAll('.ty').forEach(function(btn){btn.classList.toggle('sel',!!o&&o.type===btn.dataset.t);});
102	  document.getElementById('lv').value=o?o.lv:(sel.area>250?4:2);
103	}
104	function loadSV(){var sv=document.getElementById('sv');sv.src='/sv?id='+sel.id+'&o='+svOff+'&_='+Date.now();
105	  document.getElementById('svcap').textContent='heading '+svOff+'°';}
106	function setType(t){if(!sel)return;var lv=TYPES[t].lv;if(ovr[sel.id])lv=ovr[sel.id].lv;ovr[sel.id]={type:t,lv:lv};afterEdit();}
107	function afterEdit(){showSel();drawOverlay();updProg();}
108	function updProg(){document.getElementById('prog').textContent='('+Object.keys(ovr).length+'/'+BLD.length+')';}
109	
110	// interaction (pan/zoom/select)
111	var down=null,dragged=false,lastPx=null;
112	drc.addEventListener('pointerdown',function(e){if(e.button!==0)return;down={x:e.clientX,y:e.clientY};lastPx={x:e.clientX,y:e.clientY};dragged=false;drc.setPointerCapture(e.pointerId);});
113	drc.addEventListener('pointermove',function(e){if(!down)return;if(Math.abs(e.clientX-down.x)+Math.abs(e.clientY-down.y)>4)dragged=true;
114	  if(dragged){var a=worldAt(lastPx.x,lastPx.y),b=worldAt(e.clientX,e.clientY);if(a&&b){center.x+=a.x-b.x;center.z+=a.z-b.z;buildCam();render();}lastPx={x:e.clientX,y:e.clientY};}});
115	drc.addEventListener('pointerup',function(e){if(e.button!==0){down=null;return;}if(!dragged)selectAt(e.clientX,e.clientY);down=null;});
116	drc.addEventListener('wheel',function(e){e.preventDefault();var b4=worldAt(e.clientX,e.clientY);
117	  halfH=Math.max(30,Math.min(1500,halfH*(e.deltaY>0?1.12:0.89)));buildCam();var af=worldAt(e.clientX,e.clientY);
118	  if(b4&&af){center.x+=b4.x-af.x;center.z+=b4.z-af.z;buildCam();}render();},{passive:false});
119	
120	document.querySelectorAll('.ty').forEach(function(btn){btn.onclick=function(){setType(btn.dataset.t);};});
121	document.getElementById('applyLv').onclick=function(){if(!sel||!ovr[sel.id])return;ovr[sel.id].lv=Math.max(1,+document.getElementById('lv').value||1);afterEdit();};
122	document.getElementById('svL').onclick=function(){svOff=(svOff-40);loadSV();};
123	document.getElementById('svR').onclick=function(){svOff=(svOff+40);loadSV();};
124	document.getElementById('fill').onclick=function(){BLD.forEach(function(b){if(!ovr[b.id])ovr[b.id]={type:b.area>250?'A':'B',lv:b.area>250?4:2};});afterEdit();};
125	document.getElementById('clear').onclick=function(){ovr={};sel=null;showSel();afterEdit();};
126	function banner(t,err){var b=document.getElementById('banner');b.textContent=t;b.style.background=err?'#b03a3a':'#1e7e34';b.style.display='block';}
127	document.getElementById('save').onclick=function(){
128	  fetch('/save-buildings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({overrides:ovr})})
129	    .then(function(r){banner(r.ok?'✅ Saved! Switch to Claude and say "apply".':'Save failed',!r.ok);});
130	};
131	window.addEventListener('resize',resize);
132	// load data + world
133	fetch('/maps/mishkenot_zvulun/buildings.json').then(function(r){return r.json();}).then(function(j){
134	  BLD=j.buildings; updProg();
135	  new THREE.GLTFLoader().load('/assets/mishkenot/world.glb',function(g){
136	    g.scene.traverse(function(o){if(o.isMesh)o.material=new THREE.MeshLambertMaterial({vertexColors:true,side:THREE.DoubleSide});else if(o.isLine||o.isLineSegments)o.visible=false;});
137	    scene.add(g.scene);var bb=new THREE.Box3().setFromObject(g.scene),c=bb.getCenter(new THREE.Vector3()),s=bb.getSize(new THREE.Vector3());
138	    center={x:c.x,z:c.z};halfH=Math.max(s.x,s.z)*0.58;resize();
139	  });
140	});
141	</script></body></html>`;
142	
143	function bearing(la1,lo1,la2,lo2){var r=Math.PI/180;var y=Math.sin((lo2-lo1)*r)*Math.cos(la2*r);
144	  var x=Math.cos(la1*r)*Math.sin(la2*r)-Math.sin(la1*r)*Math.cos(la2*r)*Math.cos((lo2-lo1)*r);
145	  return (Math.atan2(y,x)/r+360)%360;}
146	
147	const server=http.createServer(async (req,res)=>{
148	  const u=new URL(req.url,'http://x');
149	  if(req.method==='POST'&&u.pathname==='/save-buildings'){let d='';req.on('data',c=>d+=c);req.on('end',()=>{
150	    try{var o=JSON.parse(d);o.savedAt=new Date().toISOString().replace(/\.\d+Z$/,'Z');o.count=Object.keys(o.overrides).length;
151	      fs.writeFileSync(OVR,JSON.stringify(o,null,2));console.log('[building-editor] SAVED '+o.count+' overrides -> building-overrides.json');
152	      res.writeHead(200);res.end('{"ok":true}');}catch(e){res.writeHead(400);res.end(String(e));}});return;}
153	  if(u.pathname==='/sv'){
154	    const b=BYID.get(u.searchParams.get('id')); const off=parseInt(u.searchParams.get('o')||'0',10)||0;
155	    if(!b||!KEY){res.writeHead(204);return res.end();}
156	    const cache=path.join(SVDIR,'bld_'+b.id+'_o'+off+'.jpg');
157	    if(fs.existsSync(cache)){res.writeHead(200,{'Content-Type':'image/jpeg'});return res.end(fs.readFileSync(cache));}
158	    try{
159	      const meta=await (await fetch('https://maps.googleapis.com/maps/api/streetview/metadata?location='+b.clat+','+b.clon+'&radius=90&key='+KEY)).json();
160	      if(meta.status!=='OK'){res.writeHead(204);return res.end();}
161	      const head=(bearing(meta.location.lat,meta.location.lng,b.clat,b.clon)+off+360)%360;
162	      const img=Buffer.from(await (await fetch('https://maps.googleapis.com/maps/api/streetview?size=480x300&location='+meta.location.lat+','+meta.location.lng+'&heading='+head.toFixed(1)+'&fov=75&pitch=8&key='+KEY)).arrayBuffer());
163	      fs.writeFileSync(cache,img);res.writeHead(200,{'Content-Type':'image/jpeg'});return res.end(img);
164	    }catch(e){res.writeHead(204);return res.end();}
165	  }
166	  if(u.pathname==='/'||u.pathname===''){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});return res.end(HTML);}
167	  const f=path.join(ROOT,decodeURIComponent(u.pathname));
168	  if(!f.startsWith(ROOT)||!fs.existsSync(f)||fs.statSync(f).isDirectory()){res.writeHead(404);return res.end('nf');}
169	  res.writeHead(200,{'Content-Type':MIME[path.extname(f)]||'application/octet-stream'});fs.createReadStream(f).pipe(res);
170	});
171	server.listen(PORT,()=>{console.log('Building editor:  http://localhost:'+PORT+'/   ('+BJSON.count+' buildings'+(KEY?'':' — NO GMAPS_KEY, Street View disabled')+')');});
